
let completed=true;function notify(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',2500);}
function refresh(){const request=document.querySelector('#request-enabled').checked;document.querySelector('#date-fields').style.display=request?'grid':'none';document.querySelector('#extension-reason-wrap').style.display=request?'block':'none';document.querySelector('#submit').textContent=request?'사진·기간 요청 제출':completed?'완료 확인 재요청 보내기':'사진·사유 제출';document.querySelector('#completed').classList.toggle('selected',completed);document.querySelector('#in-progress').classList.toggle('selected',!completed);}
document.querySelector('#completed').onclick=()=>{completed=true;refresh();};document.querySelector('#in-progress').onclick=()=>{completed=false;refresh();};document.querySelector('#request-enabled').onchange=refresh;document.querySelector('#change-photo').onclick=()=>document.querySelector('#photo-input').click();document.querySelector('#photo-input').onchange=e=>{if(e.target.files[0])document.querySelector('#evidence').src=URL.createObjectURL(e.target.files[0]);};document.querySelector('#submit').onclick=()=>{const request=document.querySelector('#request-enabled').checked;if(!completed&&!document.querySelector('#reason').value.trim())return notify('남은 작업의 사유를 입력해 주세요.');if(request&&!document.querySelector('#extension-reason').value.trim())return notify('추가 기간 요청 사유를 입력해 주세요.');if(request&&(!document.querySelector('#requested-end').value||document.querySelector('#requested-end').value<='2026-02-20'))return notify('기존 종료일 이후의 요청 종료일을 선택해 주세요.');notify(request?'시안: 제출 완료 · 기간 요청 검토 대기':completed?'시안: 완료 확인 요청 접수 · 본사 검토 대기':'시안: 사진 검토 대기');};
